<script setup>
import {ref,onMounted} from 'vue';import api from '../../services/api';import {useAuthStore} from '../../store/auth';
import GuardianPaymentInsuranceTab from './GuardianPaymentInsuranceTab.vue';import FamilyLedgerPanel from '../billing/FamilyLedgerPanel.vue';
const auth=useAuthStore(),accounts=ref([]),selected=ref(''),details=ref(null),error=ref(''),notice=ref(''),scope=ref('contact'),message=ref(''),busy=ref(false);let generation=0;
const receiptAgencies=ref([]),receiptAgency=ref(''),receipts=ref([]);
const labels={billing:'Billing',insurance:'Insurance',contact:'Contact details',scheduling:'Scheduling'};
const key=a=>`${a.clientId}:${a.agencyId}`;
async function load(){error.value='';try{const result=(await api.get('/client-support/accounts',{skipGlobalLoading:true})).data;accounts.value=result.accounts;receiptAgencies.value=result.receiptAgencies||[];if(!accounts.value.some(a=>key(a)===selected.value))selected.value=accounts.value[0]?key(accounts.value[0]):'';await open();}catch(e){details.value=null;error.value=e.response?.data?.error?.message||'Assistance accounts could not be loaded.';}}
async function open(){const run=++generation;details.value=null;message.value='';error.value='';const a=accounts.value.find(a=>key(a)===selected.value);if(!a)return;try{const r=await api.get(`/client-support/${a.clientId}`,{params:{agencyId:a.agencyId},skipGlobalLoading:true});if(run===generation){details.value=r.data;scope.value=a.scopes.includes('contact')?'contact':'scheduling';}}catch(e){if(run===generation)error.value=e.response?.data?.error?.message||'This assistance access is no longer available.';}}
async function submit(){if(busy.value)return;busy.value=true;error.value='';const run=generation,a=details.value;try{await api.post(`/client-support/${a.clientId}/requests`,{agencyId:a.agencyId,scope:scope.value,message:message.value});if(run===generation){notice.value='Your request has been sent to the office for review.';await open();}}catch(e){if(run===generation)error.value=e.response?.data?.error?.message||'Request could not be sent.';}finally{busy.value=false;}}
const when=a=>new Intl.DateTimeFormat('en-US',{dateStyle:'medium',timeStyle:'short',timeZone:a.timeZone||'America/Denver'}).format(new Date(a.startAt));
async function loadReceipts(){receipts.value=[];const agencyId=receiptAgency.value;if(!agencyId)return;try{const r=await api.get('/family-billing/receipts',{params:{agencyId,ownOnly:'1'},skipGlobalLoading:true});if(agencyId===receiptAgency.value)receipts.value=r.data.receipts;}catch{error.value='Past receipts could not be loaded.';}}
async function download(r){try{const result=await api.get(`/family-billing/receipts/${r.paymentId}.pdf`,{params:{agencyId:receiptAgency.value},responseType:'blob'});const url=URL.createObjectURL(result.data),a=document.createElement('a');a.href=url;a.download='payment-receipt.pdf';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch{error.value='This receipt could not be opened.';}}
onMounted(load);
</script>
<template><section class="support-accounts"><h2>Accounts I help with</h2><p>Each person chooses the help you can provide. These permissions do not include their password, private messages or care records.</p><button @click="load">Refresh access</button><p v-if="error" role="alert">{{error}}</p><p v-if="notice" role="status">{{notice}}</p><p v-if="!accounts.length&&!error">No independent clients have granted assistance access to this account.</p><label v-if="accounts.length">Person and agency<select v-model="selected" @change="open"><option v-for="a in accounts" :key="key(a)" :value="key(a)">{{a.clientName}} · {{a.agencyName}}</option></select></label>
<div v-if="details" :key="selected"><p class="permissions">Approved assistance: {{details.scopes.map(s=>labels[s]).join(' · ')}}</p><template v-if="details.scopes.includes('billing')||details.scopes.includes('insurance')"><GuardianPaymentInsuranceTab :agency-id="details.agencyId" :client-id="details.clientId" :guardian-user-id="auth.user.id" /></template><FamilyLedgerPanel v-if="details.scopes.includes('billing')" :agency-id="details.agencyId" :client-id="details.clientId" />
<section v-if="details.contact"><h3>Contact information</h3><p>{{details.contact.contact_phone}}<br />{{details.contact.email}}<br />{{[details.contact.address_street,details.contact.address_apt,details.contact.address_city,details.contact.address_state,details.contact.address_zip].filter(Boolean).join(', ')}}</p></section>
<section v-if="details.scopes.includes('scheduling')"><h3>Upcoming appointments</h3><p v-if="!details.appointments.length">No upcoming appointments are listed.</p><article v-for="a in details.appointments" :key="a.id"><strong>{{when(a)}}</strong><p>{{a.providerName}}</p></article></section>
<form v-if="details.scopes.includes('contact')||details.scopes.includes('scheduling')" @submit.prevent="submit"><h3>Ask the office to make a change</h3><label>Request type<select v-model="scope"><option v-if="details.scopes.includes('contact')" value="contact">Update contact information</option><option v-if="details.scopes.includes('scheduling')" value="scheduling">Change an appointment</option></select></label><label>Requested change<textarea v-model="message" rows="4" maxlength="2000" required /></label><p>Include the appointment date or contact details to update. Changes require office review; appointments remain scheduled until confirmed.</p><button :disabled="busy||!message.trim()">{{busy?'Sending…':'Send request'}}</button></form><h3 v-if="details.requests.length">Your requests</h3><p v-for="r in details.requests" :key="r.id">{{labels[r.scope]}} · {{r.status}}</p></div><section v-if="receiptAgencies.length"><h3>My past payments</h3><p>Your receipts remain available after assistance access ends.</p><label>Agency<select v-model="receiptAgency" @change="loadReceipts"><option value="">Choose an agency</option><option v-for="a in receiptAgencies" :key="a.id" :value="a.id">{{a.name}}</option></select></label><p v-if="receiptAgency&&!receipts.length">No receipts found.</p><button v-for="r in receipts" :key="r.paymentId" @click="download(r)">{{r.receiptNumber}} · Download receipt</button></section></section></template>
<style scoped>.support-accounts{padding:24px;border:1px solid #d3e0eb;border-radius:16px;background:white;color:#193653}.support-accounts label{display:grid;gap:8px;margin:16px 0}.support-accounts p{line-height:1.6}.support-accounts select,.support-accounts textarea{font:inherit;padding:12px;border:1px solid #adc3d4;border-radius:8px;width:100%;box-sizing:border-box;background:white;color:#193653}.support-accounts button{font:inherit;padding:10px 14px;border-radius:8px;cursor:pointer}.permissions{background:#edf6f2;padding:14px;border-radius:10px}.support-accounts article{border-top:1px solid #d3e0eb;padding:12px 0}.support-accounts section,.support-accounts form{margin-top:24px}[role=alert]{color:#a12424}</style>
